import os
import math
import docx
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH

def fun(x, y):
    return -0.9 * y

def analytical(x):
    return 0.12 * math.exp(-0.9 * x)

def solve_all(n=20):
    y0 = 0.12
    x0 = 0.0
    x1 = 1.0
    h = (x1 - x0) / n
    
    # 1. Euler
    euler_data = [(0, None, y0, x0, analytical(x0), 0.0)]
    y_cur = y0
    x_cur = x0
    for i in range(1, n + 1):
        k1 = fun(x_cur, y_cur)
        y_cur = y_cur + k1 * h
        x_cur = x_cur + h
        y_ex = analytical(x_cur)
        delta = abs(y_ex - y_cur)
        euler_data.append((i, k1, y_cur, x_cur, y_ex, delta))
        
    # 2. Heun
    heun_data = [(0, None, None, y0, x0, analytical(x0), 0.0)]
    y_cur = y0
    x_cur = x0
    for i in range(1, n + 1):
        k1 = fun(x_cur, y_cur)
        k2 = fun(x_cur + h, y_cur + h * k1)
        y_cur = y_cur + (k1 + k2) * h / 2
        x_cur = x_cur + h
        y_ex = analytical(x_cur)
        delta = abs(y_ex - y_cur)
        heun_data.append((i, k1, k2, y_cur, x_cur, y_ex, delta))
        
    # 3. RK4
    rk4_data = [(0, None, None, None, None, y0, x0, analytical(x0), 0.0)]
    y_cur = y0
    x_cur = x0
    for i in range(1, n + 1):
        k1 = fun(x_cur, y_cur)
        k2 = fun(x_cur + h / 2, y_cur + k1 * h / 2)
        k3 = fun(x_cur + h / 2, y_cur + k2 * h / 2)
        k4 = fun(x_cur + h, y_cur + k3 * h)
        y_cur = y_cur + (k1 + 2 * k2 + 2 * k3 + k4) * h / 6
        x_cur = x_cur + h
        y_ex = analytical(x_cur)
        delta = abs(y_ex - y_cur)
        rk4_data.append((i, k1, k2, k3, k4, y_cur, x_cur, y_ex, delta))
        
    return euler_data, heun_data, rk4_data

def fmt_num(val, dec=6, sci=False):
    if val is None:
        return ""
    if val == 0:
        return "0" if dec == 0 else f"{0:.{dec}f}".replace(".", ",")
    if sci or abs(val) < 1e-4:
        s = f"{val:.5E}"
        return s.replace(".", ",")
    s = f"{val:.{dec}f}"
    return s.replace(".", ",")

